def transform(grid):
    h,w=len(grid),len(grid[0]); out=[[2 if grid[r][c]==2 else 0 for c in range(w)] for r in range(h)]
    blocks=[(r,c) for r in range(h-1) for c in range(w-1) if all(grid[rr][cc]==2 for rr in (r,r+1) for cc in (c,c+1))]
    rec=[]
    for r,c in blocks:
        spots=[(r-1,c-1),(r-1,c+2),(r+2,c-1),(r+2,c+2)]; vals=[grid[rr][cc] for rr,cc in spots]
        rec.append((spots,[vals[2],vals[0],vals[3],vals[1]]))
    for bi,((spots,colors),(r,c)) in enumerate(zip(rec,blocks)):
        for (sr,sc),color,(dr,dc) in zip(spots,colors,[(-1,-1),(-1,1),(1,-1),(1,1)]):
            rr,cc=sr,sc
            while 0<=rr<h and 0<=cc<w:
                if grid[rr][cc]==2: break
                out[rr][cc]=color
                near=any(col==color and abs(rr-mr)+abs(cc-mc)==1 for bj,(ms,cs) in enumerate(rec) if bj!=bi for (mr,mc),col in zip(ms,cs))
                if near: break
                rr+=dr; cc+=dc
    return out
